  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver den individuelle, samlede vurdering på lægefagligt grundlag og de fire momentgrupper i overensstemmelse med vejledningen og rubrikken. Der er ingen væsentlige juridiske fejl: diagnosen gøres ikke afgørende, medvirken er 'i rimeligt omfang', og listen er illustrativ ('blandt andet')."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: individuel samlet vurdering på velbeskrevet, lægefagligt dokumenteret grundlag; hvad den uddannelsessøgende fejler og påvirkningen af daglig funktion; behandling, effekt, restsymptomer/bivirkninger og rimelig medvirken; varighed, gentagne perioder og tilbagefaldsrisiko."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden, og indeholder ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde som bestemmelse, vejledningsafsnit eller lignende. Det er ren løbende tekst uden henvisninger."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så kildernes gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen kilde, så det kan ikke vurderes, om angivne passager understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle væsentlige udsagn kan genfindes i vejledningens afsnit 3.4.1.2. Svaret tilføjer ingen ny regel, betingelse, tærskel eller myndighed."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdet er bevaret: 'blandt andet' markerer, at momenterne er eksempler, og 'i rimeligt omfang' er bevaret for medvirken. Svaret fremstiller momenterne som en del af en samlet individuel vurdering og ikke som kumulative betingelser."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: først den overordnede individuelle vurdering og dokumentationskravet, derefter de momenter, der indgår i vurderingen. Der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal være velbeskrevet og lægefagligt dokumenteret' svarer til kilden, og 'lægges der blandt andet vægt på' gengiver 'indgår f.eks.' uden at gøre listen absolut eller udtømmende. 'I rimeligt omfang' er bevaret."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "yes",
      "reason": "Svaret siger udtrykkeligt, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, og gengiver momentlisten fra A14 (hvad man fejler, daglig funktion, behandling/effekt/restsymptomer/bivirkninger/medvirken, varighed/gentagelser/tilbagefald). Eksemplerne om hovedpine og tarmsygdom samt sætningen om, at styrelsen vurderer, om der er meget betydelige begrænsninger, er ikke med, men de er ikke centrale for punktet."
    }
  },
  "overall_notes": "Indholdsmæssigt er svaret korrekt og fuldstændigt i forhold til rubrikken, og det bevarer den illustrative karakter af momentlisten. Det mangler helt kildehenvisninger, så C04 er not_met, mens C05 og C06 er not_assessable. Det understøttende element om, at en diagnose eller en andens bevilling ikke i sig selv er afgørende, er ikke eksplicit nævnt, men det er kun supporting og ikke kritisk."
}

